import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Failed to fetch the webpage: {e}")

    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0]
        headers = [th.text_content().strip() for th in table.xpath('.//th')]
        rows = []
        for tr in table.xpath('.//tr'):
            cols = [td.text_content().strip() for td in tr.xpath('.//td')]
            if cols:
                rows.append(cols)
        if not rows:
            return 0
        df = pd.DataFrame(rows, columns=headers if headers else None)
    except Exception as e:
        return 0

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")

    return len(df)

import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise ValueError("Invalid webpage URL provided.")
    if not isinstance(database_name, str) or not database_name:
        raise ValueError("Invalid database name provided.")

    try:
        response = requests.get(webpage_url, timeout=10)
        response.raise_for_status()
        tree = html.fromstring(response.content)
        table_elements = tree.xpath('//table')
        if not table_elements:
            return 0

        table = table_elements[0]
        headers = [header.text.strip() for header in table.xpath('.//th')]
        rows = []
        for row in table.xpath('.//tr'):
            cols = row.xpath('.//td')
            if not cols:
                continue
            rows.append([col.text.strip() for col in cols])

        if not rows:
            return 0

        df = pd.DataFrame(rows, columns=headers if headers else None)
    except requests.RequestException as e:
        raise requests.RequestException(f"Error fetching webpage: {e}") from e
    except Exception as e:
        raise ValueError(f"Error processing HTML content: {e}") from e

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql("my_table", conn, if_exists="replace", index=False)
        row_count = len(df)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Error with SQLite database: {e}") from e

    return row_count

